from main import app
from fastapi.testclient import TestClient

def test_get_all_players_each_player_has_required_fields():
    client = TestClient(app)
    r = client.get('/players/')
    assert r.status_code == 200
    body = r.json()
    assert len(body) == 26
    required = {'id', 'firstName', 'lastName', 'squadNumber', 'position'}
    for player in body:
        for field in required:
            assert field in player, f'Missing field {field} in {player}'

test_get_all_players_each_player_has_required_fields()
